async function buildPayrollJournal(cid, runId, dx = db) {
  const [run] = await dx.select().from(payrollRunsTable).where(and(eq(payrollRunsTable.id, runId), eq(payrollRunsTable.companyId, cid)));
  if (!run) throw new Error("\u0645\u0633\u064A\u0631 \u0627\u0644\u0631\u0648\u0627\u062A\u0628 \u063A\u064A\u0631 \u0645\u0648\u062C\u0648\u062F");
  const lines = await dx.select().from(payrollLinesTable).where(eq(payrollLinesTable.payrollRunId, runId));
  if (!lines.length) throw new Error("\u0644\u0627 \u062A\u0648\u062C\u062F \u0633\u0637\u0648\u0631 \u0641\u064A \u0627\u0644\u0645\u0633\u064A\u0631");
  let salariesEarned = 0;
  let allowances = 0;
  let netPayable = 0;
  let gosiEmployee = 0;
  let loanDeduction = 0;
  let otherDeduction = 0;
  for (const l2 of lines) {
    salariesEarned += num2(l2.basicSalary) + num2(l2.overtimeAmount) + num2(l2.bonusAmount) - num2(l2.absenceDeduction);
    allowances += num2(l2.housingAllow) + num2(l2.transportAllow) + num2(l2.otherAllow);
    netPayable += num2(l2.netSalary);
    gosiEmployee += num2(l2.gosiEmployee);
    loanDeduction += num2(l2.loanDeduction);
    otherDeduction += num2(l2.otherDeduction) + num2(l2.violationDeduction);
  }
  const accounts = await resolveHrAccounts(cid, true, dx);
  const missing = [];
  if (salariesEarned > 0 && !accounts.salariesExpense) missing.push("\u0645\u0635\u0631\u0648\u0641 \u0627\u0644\u0631\u0648\u0627\u062A\u0628 (5201)");
  if (allowances > 0 && !accounts.allowancesExpense) missing.push("\u0645\u0635\u0631\u0648\u0641 \u0627\u0644\u0628\u062F\u0644\u0627\u062A (5202)");
  if (netPayable > 0 && !accounts.salariesPayable) missing.push("\u0627\u0644\u0631\u0648\u0627\u062A\u0628 \u0627\u0644\u0645\u0633\u062A\u062D\u0642\u0629 (21051)");
  if (gosiEmployee > 0 && !accounts.gosiPayable) missing.push("\u0627\u0644\u062A\u0623\u0645\u064A\u0646\u0627\u062A \u0627\u0644\u0645\u0633\u062A\u062D\u0642\u0629 (21052)");
  if (loanDeduction > 0 && !accounts.employeeLoans) missing.push("\u0633\u0644\u0641 \u0627\u0644\u0645\u0648\u0638\u0641\u064A\u0646 (11081)");
  if (otherDeduction > 0 && !accounts.otherDeductions) missing.push("\u0627\u0633\u062A\u0642\u0637\u0627\u0639\u0627\u062A \u0623\u062E\u0631\u0649 (21053)");
  if (missing.length) throw new Error("\u0627\u0644\u062D\u0633\u0627\u0628\u0627\u062A \u0627\u0644\u062A\u0627\u0644\u064A\u0629 \u063A\u064A\u0631 \u0645\u0631\u0628\u0648\u0637\u0629 \u0641\u064A \u0625\u0639\u062F\u0627\u062F\u0627\u062A \u0627\u0644\u0645\u0648\u0627\u0631\u062F \u0627\u0644\u0628\u0634\u0631\u064A\u0629: " + missing.join("\u060C "));
  const totalDr = +(salariesEarned + allowances).toFixed(2);
  const totalCr = +(netPayable + gosiEmployee + loanDeduction + otherDeduction).toFixed(2);
  if (Math.abs(totalDr - totalCr) > 0.05) {
    throw new Error(`\u0627\u0644\u0642\u064A\u062F \u063A\u064A\u0631 \u0645\u062A\u0648\u0627\u0632\u0646: \u0645\u062F\u064A\u0646 ${fix(totalDr)} \u2260 \u062F\u0627\u0626\u0646 ${fix(totalCr)}`);
  }
  const period2 = `${String(run.month).padStart(2, "0")}/${run.year}`;
  const desc7 = `\u0642\u064A\u062F \u0645\u0633\u064A\u0631 \u0627\u0644\u0631\u0648\u0627\u062A\u0628 ${run.code} \u0639\u0646 \u0627\u0644\u0641\u062A\u0631\u0629 ${period2}`;
  const payrollDate = run.payDate || run.periodEnd;
  const prW = await assertWritableForDate(cid, payrollDate);
  if (!prW.ok) throw new Error(prW.reason);
  const jeDocNumber = await resolveJeNumber({
    companyId: cid,
    sourceType: "payroll_run",
    sourceId: runId,
    subType: "hr_payroll",
    branchId: run.branchId ?? null,
    docDate: payrollDate,
    userId: null,
    dx
  }) ?? run.code;
  const [entry] = await dx.insert(journalEntriesTable).values({
    companyId: cid,
    branchId: run.branchId ?? null,
    docNumber: jeDocNumber,
    entryDate: payrollDate,
    currency: "SAR",
    exchangeRate: "1",
    description: desc7,
    entryType: "payroll_run",
    status: await resolvePostingStatus(cid, "payroll")
  }).returning();
  const drLines = [];
  if (salariesEarned > 0)
    drLines.push({
      entryId: entry.id,
      accountId: accounts.salariesExpense,
      debit: fix(salariesEarned),
      credit: "0.00",
      description: `\u0631\u0648\u0627\u062A\u0628 \u0648\u0623\u062C\u0648\u0631 \u0627\u0644\u0641\u062A\u0631\u0629 ${period2}`,
      sortOrder: 0
    });
  if (allowances > 0)
    drLines.push({
      entryId: entry.id,
      accountId: accounts.allowancesExpense,
      debit: fix(allowances),
      credit: "0.00",
      description: `\u0628\u062F\u0644\u0627\u062A \u0648\u062D\u0648\u0627\u0641\u0632 \u0627\u0644\u0641\u062A\u0631\u0629 ${period2}`,
      sortOrder: 1
    });
  const crLines = [];
  if (netPayable > 0)
    crLines.push({
      entryId: entry.id,
      accountId: accounts.salariesPayable,
      debit: "0.00",
      credit: fix(netPayable),
      description: `\u0635\u0627\u0641\u064A \u0627\u0644\u0631\u0648\u0627\u062A\u0628 \u0627\u0644\u0645\u0633\u062A\u062D\u0642\u0629 ${period2}`,
      sortOrder: 2
    });
  if (gosiEmployee > 0)
    crLines.push({
      entryId: entry.id,
      accountId: accounts.gosiPayable,
      debit: "0.00",
      credit: fix(gosiEmployee),
      description: `\u062D\u0635\u0629 \u0627\u0644\u0645\u0648\u0638\u0641 \u0645\u0646 \u0627\u0644\u062A\u0623\u0645\u064A\u0646\u0627\u062A ${period2}`,
      sortOrder: 3
    });
  if (loanDeduction > 0)
    crLines.push({
      entryId: entry.id,
      accountId: accounts.employeeLoans,
      debit: "0.00",
      credit: fix(loanDeduction),
      description: `\u0627\u0633\u062A\u0631\u062F\u0627\u062F \u0623\u0642\u0633\u0627\u0637 \u0633\u0644\u0641 \u0627\u0644\u0645\u0648\u0638\u0641\u064A\u0646 ${period2}`,
      sortOrder: 4
    });
  if (otherDeduction > 0)
    crLines.push({
      entryId: entry.id,
      accountId: accounts.otherDeductions,
      debit: "0.00",
      credit: fix(otherDeduction),
      description: `\u0627\u0633\u062A\u0642\u0637\u0627\u0639\u0627\u062A \u0623\u062E\u0631\u0649 ${period2}`,
      sortOrder: 5
    });
  await dx.insert(journalEntryLinesTable).values([...drLines, ...crLines]);
  return entry.id;
}
