async function retrieveStandards(question, scope2) {
  const tokens = Array.from(new Set(
    question.toLowerCase().replace(/[^\u0600-\u06FFa-z0-9\s]/gi, " ").split(/\s+/).filter((t2) => t2.length >= 2)
  )).slice(0, 12);
  if (tokens.length === 0) return [];
  const orClauses = tokens.map((t2) => sql`(title_ar ILIKE ${"%" + t2 + "%"} OR title_en ILIKE ${"%" + t2 + "%"} OR summary_ar ILIKE ${"%" + t2 + "%"} OR full_text_ar ILIKE ${"%" + t2 + "%"} OR EXISTS (SELECT 1 FROM jsonb_array_elements_text(tags) tg WHERE tg ILIKE ${"%" + t2 + "%"}))`);
  const matchAny = orClauses.reduce((acc, c, i2) => i2 === 0 ? c : sql`${acc} OR ${c}`, sql``);
  const scoreParts = tokens.map((t2) => sql`
    (CASE WHEN title_ar    ILIKE ${"%" + t2 + "%"} THEN 5 ELSE 0 END) +
    (CASE WHEN title_en    ILIKE ${"%" + t2 + "%"} THEN 4 ELSE 0 END) +
    (CASE WHEN summary_ar  ILIKE ${"%" + t2 + "%"} THEN 3 ELSE 0 END) +
    (CASE WHEN full_text_ar ILIKE ${"%" + t2 + "%"} THEN 1 ELSE 0 END) +
    (CASE WHEN EXISTS (SELECT 1 FROM jsonb_array_elements_text(tags) tg WHERE tg ILIKE ${"%" + t2 + "%"}) THEN 4 ELSE 0 END)
  `);
  const scoreExpr = scoreParts.reduce((acc, p, i2) => i2 === 0 ? p : sql`${acc} + ${p}`, sql``);
  const scopeClause = scope2 ? sql` AND standard = ${scope2}` : sql``;
  const r3 = await db.execute(sql`
    SELECT id, code, standard, title_ar, summary_ar, full_text_ar,
           (${scoreExpr}) AS score
      FROM accounting_standards_kb
     WHERE (${matchAny}) ${scopeClause}
     ORDER BY score DESC
     LIMIT 4
  `);
  return (r3.rows ?? []).map((row) => ({
    id: row.id,
    code: row.code,
    standard: row.standard,
    titleAr: row.title_ar,
    summaryAr: row.summary_ar,
    fullTextAr: row.full_text_ar,
    score: Number(row.score) || 0
  }));
}
