      sales: ["sales_module", "sales_reports", "customers"],
      purchasing: ["purchases_module", "purchases_reports", "suppliers"],
      cash: ["cash_module", "cash_reports"],
      accounting: ["accounts", "accounting_reports"],
      hr: ["hr_module"],
      zatca: ["zatca", "reports"],
