async function bootstrap() {
  const schemaBootBudgetMs = (() => {
    const n2 = Number(process.env["SCHEMA_BOOT_BUDGET_MS"]);
    return Number.isFinite(n2) && n2 > 0 ? Math.floor(n2) : 2e4;
  })();
  const schemaReady = ensureSchemaUpToDate().catch((err) => {
    logger.error({ err }, "Failed to ensure schema is up to date \u2014 server will continue but auth may fail");
  });
  let budgetTimer;
  await Promise.race([
    schemaReady,
    new Promise((resolve2) => {
      budgetTimer = setTimeout(() => {
        logger.warn(
          { budgetMs: schemaBootBudgetMs },
          "ensureSchema exceeded boot budget \u2014 opening port now; reconciliation continues in background"
        );
        resolve2();
      }, schemaBootBudgetMs);
      budgetTimer.unref?.();
    })
  ]);
  if (budgetTimer) clearTimeout(budgetTimer);
  try {
    const { warmEmailConfig: warmEmailConfig2 } = await Promise.resolve().then(() => (init_email(), email_exports));
    await warmEmailConfig2();
  } catch (err) {
    logger.warn({ err }, "warmEmailConfig failed at startup");
  }
  await rebrandSpaIndexOnDiskForAgent();
  await disableLegacyAgentAutoUpdater();
  const httpServer = http4.createServer(app_default);
  attachCobrowseHub(httpServer);
  attachTrainingP2PHub(httpServer);
  httpServer.listen(port, (err) => {
    if (err) {
      logger.error({ err }, "Error listening on port");
      process.exit(1);
    }
    logger.info({ port }, "Server listening");
    seedSuperAdmin();
    seedPlanConfigs();
    seedIndustries();
    Promise.resolve().then(() => (init_seedSupportKB(), seedSupportKB_exports)).then((m2) => m2.seedSupportKB()).catch(
      (err2) => logger.error({ err: err2 }, "seedSupportKB failed (assistant will still work without seed)")
    );
    Promise.resolve().then(() => (init_seedAccountingStandardsKb(), seedAccountingStandardsKb_exports)).then((m2) => m2.seedAccountingStandardsKb()).catch(
      (err2) => logger.error({ err: err2 }, "seedAccountingStandardsKb failed (accounting AI will still work without seed)")
    );
    Promise.resolve().then(() => (init_backup(), backup_exports)).then((m2) => m2.startBackupScheduler?.()).catch(() => {
    });
    startAutoSuspendScheduler();
    Promise.resolve().then(() => (init_reportScheduler(), reportScheduler_exports)).then((m2) => m2.startReportDigestScheduler?.()).catch(() => {
    });
    Promise.resolve().then(() => (init_maintenanceScheduler(), maintenanceScheduler_exports)).then((m2) => m2.startMaintenanceScheduler?.()).catch(() => {
    });
    Promise.resolve().then(() => (init_depreciationScheduler(), depreciationScheduler_exports)).then((m2) => m2.startFaDepreciationScheduler?.()).catch(() => {
    });
    Promise.resolve().then(() => (init_adjustmentScheduler(), adjustmentScheduler_exports)).then((m2) => m2.startAdjustmentScheduler?.()).catch(() => {
    });
    Promise.resolve().then(() => (init_posSessionJanitor(), posSessionJanitor_exports)).then((m2) => m2.startPosSessionAutoCloseScheduler?.()).catch(() => {
    });
    Promise.resolve().then(() => (init_githubReleaseSync(), githubReleaseSync_exports)).then((m2) => m2.startGithubReleaseSyncScheduler?.()).catch(() => {
    });
  });
}
bootstrap();
